class Solution:
    def searchInsert(self, nums: List[int], target: int) -> int:
        n = len(nums)
        l, r = 0, n - 1
        ans = n

        while l <= r:
            mid = (l + r) // 2

            if nums[mid] >= target:
                ans = mid
                r -= 1
            else:
                l += 1

        return ans
